INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.88.0',
  '2026-09-17',
  'Пульт ТВ: приложение для Android TV',
  E'Появилось приложение «Habits TV» для приставки. Браузер приставки водит курсором, а в приложении медиатекой управляют стрелками пульта: вправо-влево-вниз по плиткам, OK открывает. «Начать» нажимать не нужно — всё открывается сразу.\n\n«Назад» на пульте делает шаг назад: из плеера, с экрана сериала, из папки; на главной — закрывает приложение. Долгое нажатие «Назад» или кнопка «⚙ Адрес» в шапке открывают адрес медиатеки: если роутер выдал компьютеру другой адрес, его меняют там, без переустановки. Если медиатека не открылась, приложение так и скажет и предложит повторить или сменить адрес.\n\nСкачать приложение можно по значку Android в правом краю шапки медиатеки, если открыть её в браузере.',
  E'habits/tv-app: одна Activity с WebView (Java, без библиотек, APK 21 КБ) и экран адреса. User-Agent дополняется «HabitsTV/»: плеер по нему пропускает «Начать» (mediaPlaybackRequiresUserGesture=false), показывает «⚙ Адрес» (мост HabitsApp.openSettings) и отдаёт кнопку «Назад» в window.habitsBack() — true, если было куда вернуться, иначе приложение закрывается. Долгое «Назад» — по KeyEvent.isLongPress, с запасным порогом 800 мс. LEANBACK_LAUNCHER и баннер 320×180 — чтобы значок был на главном экране Android TV; сенсорный экран и leanback не обязательны. usesCleartextTraffic — медиатека по http в домашней сети.\n\ntargetSdk 34, а не 36, и enableOnBackInvokedCallback=false: при targetSdk 36 «Назад» забирал системный жест predictive back, dispatchKeyEvent его не получал, и кнопка закрывала приложение вместо шага назад — поймано в эмуляторе. Ключ подписи создаётся build.sh в ~/.config/habits-tv/ вне репозитория.\n\nМедиаагент раздаёт APK по /app/habits-tv.apk из кэша (build.sh --deploy); страница в браузере показывает значок Android, только если HEAD вернул 200.\n\nПроверено в эмуляторе Android 16 с экраном 1920×1080 при плотности 320 (960 CSS-пикселей, как на приставке) против живой медиатеки мини-сервера: страница без «Начать», стрелки по сетке плиток с прокруткой, OK открывает сериал, серия играет без жеста, «Назад» из экрана сериала и из плеера, выход с главной, долгое «Назад» → адрес, неверный адрес → экран ошибки → смена адреса пультом, «⚙ Адрес» со страницы. На настоящей приставке ещё не проверялось.'
);
-- +goose StatementEnd

